// ── Hero Highlights: Typewriter + Tech Chips ──────────────────────────────
const ROLES = [
  'Full Stack Developer',
  'Blockchain Engineer',
  'Smart Contract Dev',
  'DeFi Protocol Builder',
  'Web3 Dev',
];

const TECH_CHIPS = [
  { label: 'Ethereum', color: '#627eea' },
  { label: 'Solana', color: '#9945ff' },
  { label: 'Solidity', color: '#627eea' },
  { label: 'Rust', color: '#f74c00' },
  { label: 'React', color: '#3178c6' },
  { label: 'Spring Boot', color: '#6db33f' },
  { label: 'Node.js', color: '#68a063' },
];

function HeroHighlights({ darkMode }: { darkMode: boolean }) {
  const [roleIdx, setRoleIdx] = useState(0);
  const [displayed, setDisplayed] = useState('');
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    const fullText = ROLES[roleIdx];
    let timeout: ReturnType<typeof setTimeout>;

    if (!deleting && displayed.length < fullText.length) {
      timeout = setTimeout(() => setDisplayed(fullText.slice(0, displayed.length + 1)), 60);
    } else if (!deleting && displayed.length === fullText.length) {
      timeout = setTimeout(() => setDeleting(true), 2000);
    } else if (deleting && displayed.length > 0) {
      timeout = setTimeout(() => setDisplayed(displayed.slice(0, -1)), 35);
    } else if (deleting && displayed.length === 0) {
      setDeleting(false);
      setRoleIdx((i) => (i + 1) % ROLES.length);
    }
    return () => clearTimeout(timeout);
  }, [displayed, deleting, roleIdx]);

  return (
    <div style={{ marginBottom: '36px' }}>
      {/* Typewriter role line */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: '4px',
        marginBottom: '24px',
        minHeight: '36px',
      }}>
        <span style={{
          fontSize: 'clamp(0.95rem, 2vw, 1.15rem)',
          fontWeight: 600,
          color: darkMode ? '#e2e8f0' : '#334155',
        }}>
          I build{' '}
        </span>
        <span style={{
          fontSize: 'clamp(0.95rem, 2vw, 1.15rem)',
          fontWeight: 700,
          background: 'linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          backgroundClip: 'text',
          minWidth: '220px',
        }}>
          {displayed}
        </span>
        {/* Blinking cursor */}
        <span style={{
          display: 'inline-block',
          width: '2px',
          height: '22px',
          background: '#3b82f6',
          borderRadius: '2px',
          animation: 'blink 1s step-end infinite',
          flexShrink: 0,
        }} />
        <style>{`@keyframes blink { 0%,100%{opacity:1} 50%{opacity:0} }`}</style>
      </div>

      {/* Tech chip pills */}
      <div style={{
        display: 'flex',
        flexWrap: 'wrap',
        gap: '8px',
      }}>
        {TECH_CHIPS.map(({ label, color }) => (
          <span
            key={label}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: '6px',
              padding: '5px 12px',
              borderRadius: '999px',
              fontSize: '12px',
              fontWeight: 600,
              letterSpacing: '0.02em',
              border: `1px solid ${color}40`,
              background: `${color}12`,
              color: color,
              cursor: 'default',
              transition: 'transform 0.2s, box-shadow 0.2s',
            }}
            onMouseEnter={e => {
              const el = e.currentTarget as HTMLSpanElement;
              el.style.transform = 'translateY(-2px)';
              el.style.boxShadow = `0 4px 12px ${color}40`;
            }}
            onMouseLeave={e => {
              const el = e.currentTarget as HTMLSpanElement;
              el.style.transform = '';
              el.style.boxShadow = '';
            }}
          >
            <span style={{
              width: '6px', height: '6px',
              borderRadius: '50%',
              background: color,
              flexShrink: 0,
            }} />
            {label}
          </span>
        ))}
      </div>
    </div>
  );
}
